import type { IconProps } from "./icon";

/*
 * Animated icons with state. Each takes a boolean (or small value) and moves between its states with shape changes:
 * lines rotate into a cross, a check draws itself, a lock's shackle lifts. They are server-compatible (the motion is
 * CSS on `data-*` state) and hold still under reduced motion. Loaders loop; slow under reduced motion, not stopped.
 */
const steps = { xs: 12, sm: 16, md: 20, lg: 24, xl: 32 } as const;

type StateIconProps = Omit<IconProps, "animate" | "animateOn">;

function Svg({
  name,
  size = "1em",
  strokeWidth = 1.75,
  title,
  className,
  children,
  data,
  ...rest
}: StateIconProps & { name: string; children: React.ReactNode; data?: Record<string, string | undefined> }) {
  const px = typeof size === "string" && size in steps ? steps[size as keyof typeof steps] : size;
  return (
    <svg
      viewBox="0 0 24 24"
      width={px}
      height={px}
      fill="none"
      stroke="currentColor"
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      role={title ? "img" : undefined}
      aria-hidden={title ? undefined : true}
      focusable="false"
      className={className ? `hm-icon hm-ai hm-ai-${name} ${className}` : `hm-icon hm-ai hm-ai-${name}`}
      {...data}
      {...rest}
    >
      {title ? <title>{title}</title> : null}
      {children}
    </svg>
  );
}
const flag = (on: boolean | undefined) => (on ? "" : undefined);

/** Three lines that turn into a cross. */
export function MenuCloseIcon({ open = false, ...p }: StateIconProps & { open?: boolean }) {
  return (
    <Svg name="menu" data={{ "data-open": flag(open) }} {...p}>
      <path className="hm-ai-top" d="M4 7h16" />
      <path className="hm-ai-mid" d="M4 12h16" />
      <path className="hm-ai-bot" d="M4 17h16" />
    </Svg>
  );
}

/** A plus that turns into a cross (a quarter turn with a spring). */
export function PlusCloseIcon({ open = false, ...p }: StateIconProps & { open?: boolean }) {
  return (
    <Svg name="plus" data={{ "data-open": flag(open) }} {...p}>
      <g className="hm-ai-turn">
        <path d="M12 5v14" />
        <path d="M5 12h14" />
      </g>
    </Svg>
  );
}

/** A chevron that turns over: `down` points down when closed and up when open; `right` points right, then down. */
export function ChevronToggleIcon({
  open = false,
  direction = "down",
  ...p
}: StateIconProps & { open?: boolean; direction?: "down" | "right" }) {
  return (
    <Svg name="chevron" data={{ "data-open": flag(open), "data-direction": direction }} {...p}>
      <path className="hm-ai-turn" d="M7 10l5 5 5-5" />
    </Svg>
  );
}

/** A play triangle that becomes two pause bars (the shapes morph in browsers that animate path data). */
export function PlayPauseIcon({ playing = false, ...p }: StateIconProps & { playing?: boolean }) {
  return (
    <Svg name="playpause" data={{ "data-playing": flag(playing) }} {...p}>
      <path className="hm-ai-l" d="M7.5 5.5L12 8.2V15.8L7.5 18.5Z" fill="currentColor" />
      <path className="hm-ai-r" d="M12 8.2L17.5 12L17.5 12L12 15.8Z" fill="currentColor" />
    </Svg>
  );
}

/** A circle and a check that draw themselves when `active` turns on. */
export function SuccessIcon({ active = true, ...p }: StateIconProps & { active?: boolean }) {
  return (
    <Svg name="draw" data={{ "data-active": flag(active) }} {...p}>
      <circle className="hm-ai-ring" cx="12" cy="12" r="9" pathLength={1} />
      <path className="hm-ai-mark" d="M7.8 12.4l2.9 2.9 5.5-6" pathLength={1} />
    </Svg>
  );
}

/** A circle and a cross that draw themselves, then shake. */
export function ErrorIcon({ active = true, ...p }: StateIconProps & { active?: boolean }) {
  return (
    <Svg name="draw" data={{ "data-active": flag(active), "data-shake": "" }} {...p}>
      <circle className="hm-ai-ring" cx="12" cy="12" r="9" pathLength={1} />
      <path className="hm-ai-mark" d="M9 9l6 6" pathLength={1} />
      <path className="hm-ai-mark hm-ai-mark-2" d="M15 9l-6 6" pathLength={1} />
    </Svg>
  );
}

/** A heart that fills and pops when `liked`. */
export function LikeIcon({ liked = false, ...p }: StateIconProps & { liked?: boolean }) {
  const d = "M12 19.8s-7.3-4.4-7.3-9.8A4.2 4.2 0 0 1 12 7.4 4.2 4.2 0 0 1 19.3 10c0 5.4-7.3 9.8-7.3 9.8z";
  return (
    <Svg name="like" data={{ "data-active": flag(liked) }} {...p}>
      <path className="hm-ai-fill" d={d} fill="currentColor" />
      <path d={d} />
    </Svg>
  );
}

