/** A speaker with sound waves; muting retracts the waves and draws a cross. `level` is 0 to 2 waves. */
export function VolumeToggleIcon({
  muted = false,
  level = 2,
  ...p
}: StateIconProps & { muted?: boolean; level?: 0 | 1 | 2 }) {
  return (
    <Svg name="volume" data={{ "data-muted": flag(muted), "data-level": String(level) }} {...p}>
      <path d="M4.500 9.500h3L12 6v12l-4.500-3.500h-3z" />
      <path className="hm-ai-wave hm-ai-wave-1" d="M15.200 9.600a3.500 3.500 0 0 1 0 4.800" pathLength={1} />
      <path className="hm-ai-wave hm-ai-wave-2" d="M17.900 7a7 7 0 0 1 0 10" pathLength={1} />
      <path className="hm-ai-cross" d="M15.500 9.500l5 5" pathLength={1} />
      <path className="hm-ai-cross hm-ai-cross-2" d="M20.500 9.500l-5 5" pathLength={1} />
    </Svg>
  );
}

/** An eye that closes with a slash drawn across it when `hidden`. */
export function EyeToggleIcon({ hidden = false, ...p }: StateIconProps & { hidden?: boolean }) {
  return (
    <Svg name="eye" data={{ "data-hidden": flag(hidden) }} {...p}>
      <path d="M2.500 12s3.500-6.500 9.500-6.500S21.500 12 21.500 12 18 18.500 12 18.500 2.500 12 2.500 12z" />
      <circle className="hm-ai-pupil" cx="12" cy="12" r="2.800" />
      <path className="hm-ai-slash" d="M4.500 4.500l15 15" pathLength={1} />
    </Svg>
  );
}

